import{_ as a,o as r,c as e,ai as l}from"./chunks/framework.C33Uq6m-.js";const c=JSON.parse('{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/index.md","filePath":"zh/guide/index.md"}'),o={name:"zh/guide/index.md"};function n(s,t,i,d,h,g){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h1><p><strong>LLMxRay</strong> 是一个免费的、本地优先的面板，连接运行在你自己机器上的 <a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a>。你可以用它和任何已下载的模型对话，然后查看幕后发生的一切：每个 token 到达得有多快、模型可能在「想」什么、不同设置如何改变输出，以及更多。</p><p><strong>无云端。无 API key。无费用。</strong> 一切都在你自己的硬件上运行。</p><h2 id="这是给谁用的" tabindex="-1">这是给谁用的？ <a class="header-anchor" href="#这是给谁用的" aria-label="Permalink to &quot;这是给谁用的？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>如果你是……</th><th>LLMxRay 可以帮你……</th></tr></thead><tbody><tr><td><strong>好奇的初学者</strong></td><td>实时看着 AI 的回答成形，弄明白「温度」「token」到底是什么意思</td></tr><tr><td><strong>学生 / 教师</strong></td><td>用可视化的方式探索模型行为 —— 非常适合 AI/ML 课程与演示</td></tr><tr><td><strong>开发者</strong></td><td>调试提示词、对比模型、分析延迟、检查工具调用</td></tr><tr><td><strong>研究者</strong></td><td>做受控实验：同一个提示词，不同设置，结果并排对照</td></tr></tbody></table><h2 id="界面导航" tabindex="-1">界面导航 <a class="header-anchor" href="#界面导航" aria-label="Permalink to &quot;界面导航&quot;">​</a></h2><p>LLMxRay 的侧边栏有 12 个导航项，每一项对应一个主要功能。本指南按照它们在侧边栏中出现的顺序，每项一章：</p><ol><li><strong><a href="./chat-diagnostics.html">对话诊断</a></strong> —— 主对话界面，带流式输出与会话分析</li><li><strong><a href="/llmxray/docs/en/guide/compare.html">对比</a></strong> —— 模型与设置的并排对照 <ul><li><strong><a href="/llmxray/docs/en/guide/language-compare.html">语言对比</a></strong> —— 理解不同语言的「token 税」</li></ul></li><li><strong><a href="/llmxray/docs/en/guide/embeddings.html">嵌入</a></strong> —— 文本嵌入的可视化与相似度</li><li><strong><a href="/llmxray/docs/en/guide/knowledge-base.html">知识库</a></strong> —— 文档上传、切分与 RAG 检索</li><li><strong><a href="/llmxray/docs/en/guide/tool-workshop.html">工具工坊</a></strong> —— 可视化工具构建器，代码双向同步</li><li><strong><a href="/llmxray/docs/en/guide/fim.html">中间填充（FIM）</a></strong> —— 面向支持 FIM 的模型的代码补全实验台</li><li><strong><a href="./cache-lab.html">缓存实验室</a></strong> —— 测量提示词为何未命中 KV 缓存，以及每轮为此付出的代价</li><li><strong><a href="/llmxray/docs/en/guide/protocols.html">协议观察台</a></strong> —— 同一个提示词分别走原生、OpenAI 兼容和 Anthropic 兼容接口，对比同一个本地模型的表现</li><li><strong><a href="/llmxray/docs/en/guide/ai-training.html">AI 训练</a></strong> —— 训练数据的整理与导出</li><li><strong><a href="/llmxray/docs/en/guide/models.html">模型</a></strong> —— 模型浏览器与能力检测</li><li><strong><a href="/llmxray/docs/en/guide/benchmark.html">基准测试</a></strong> —— 基于 logprobs 的标准化模型评测</li><li><strong><a href="/llmxray/docs/en/guide/system.html">我的系统</a></strong> —— 硬件检测与 Ollama 状态</li><li><strong><a href="/llmxray/docs/en/guide/settings.html">设置</a></strong> —— 连接、参数与偏好</li></ol><h2 id="其他元素" tabindex="-1">其他元素 <a class="header-anchor" href="#其他元素" aria-label="Permalink to &quot;其他元素&quot;">​</a></h2><ul><li><strong>顶栏</strong> —— 显示当前页面标题、主题切换（深色 / 浅色），以及 Ollama 连接状态（绿色 = 已连接，红色 = 未连接）。</li><li><strong>反馈按钮</strong> —— 位于侧边栏底部，点击后可直接提交反馈。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>如果你还没有安装 LLMxRay，请前往<a href="./installation.html">安装</a>页面。否则，从侧边栏任选一章开始探索。</p><div class="tip custom-block"><p class="custom-block-title">关于本中文文档</p><p>中文文档目前覆盖首页、安装、对话诊断和缓存实验室。其余章节仍为英文，正在陆续翻译中。界面本身已完整汉化。</p></div>',13)])])}const u=a(o,[["render",n]]);export{c as __pageData,u as default};
